//! The iterator helpers (J4.4a): `Iterator`, its prototype's methods,
//! `from`, `concat`, `zip` and `zipKeyed`, as the reference browser
//! gives them (the J4.4 probe, Chrome 158).

use crate::agent::{Agent, AgentOptions, Outcome};

fn run(src: &str) -> String {
    let mut agent = Agent::new(AgentOptions::default());
    agent.scope(|scope| match scope.run_script_named(src, "i.js") {
        Ok(Outcome::Value(v)) => scope.to_text(v).unwrap_or_default(),
        Ok(Outcome::Threw(e)) => format!("throw {}", scope.to_text(e).unwrap_or_default()),
        Ok(Outcome::Terminated) => "terminated".into(),
        Err(e) => format!("compile error: {e}"),
    })
}

#[test]
fn helpers_close_skip_and_check_as_the_spec_says() {
    // take(0) closes at the first next; return before the first next
    // closes what it iterates; includes skips, then SameValueZero, and
    // checks its count; join's nullish values; drop; zip's strict mode;
    // from's own iterators; a subclass; the constructor setter on
    // another object; [Symbol.dispose] calls return.
    assert_eq!(
        run("var closed = 0; \
             function src() { return { __proto__: Iterator.prototype, next: function () { return { done: false, value: 1 }; }, \
                                        return: function () { closed++; return {}; } }; } \
             var r = []; src().take(0).next(); r.push(closed); \
             src().map(function (x) { return x; }).return(); r.push(closed); \
             var h = src().filter(function () { return true; }); h.next(); h.return(); r.push(closed); \
             r.push([1, 2, 3].values().includes(1, 1), [1, 2, 3].values().includes(3, 2), [NaN].values().includes(NaN), \
                    [0].values().includes(-0)); \
             var e = []; \
             [['1', 'a'], [-1, 'b'], [1.5, 'c'], [NaN, 'd']].forEach(function (p) { \
               try { src().includes(0, p[0]); } catch (x) { e.push(x.name); } }); \
             r.push(e.join('/'), closed); \
             r.push([1, null, undefined, 'a'].values().join('-'), [1, 2, 3, 4].values().drop(2).toArray().join('/')); \
             try { Iterator.zip([[1], [1, 2]], { mode: 'strict' }).toArray(); } catch (x) { r.push(x.name); } \
             r.push(Iterator.zip([[1], [2]], { mode: 'strict' }).toArray().length); \
             var a = [].values(); r.push(Iterator.from(a) === a, Iterator.from({ next: function () {} }) instanceof Iterator); \
             class C extends Iterator {} r.push(new C() instanceof Iterator); \
             var o = Object.create(Iterator.prototype); o.constructor = 5; \
             r.push(o.hasOwnProperty('constructor'), o.constructor); \
             var d = 0; ({ __proto__: Iterator.prototype, return: function () { d++; return {}; } })[Symbol.dispose](); r.push(d); \
             r.join()"),
        "1,2,3,false,true,true,true,TypeError/RangeError/TypeError/TypeError,7,1---a,3/4,TypeError,1,\
         true,true,true,true,5,1"
    );
}

#[test]
fn helpers_survive_collection() {
    let mut agent = Agent::new(AgentOptions::default());
    agent.set_stress(true);
    let got = agent.scope(|scope| {
        match scope.run_script(
            "var big = []; for (var i = 0; i < 50; i++) big.push({ v: i }); \
             var r = Iterator.from(big).filter(function (o) { return o.v % 3 === 0; }) \
               .map(function (o) { return { w: o.v * 2 }; }) \
               .flatMap(function (o) { return [o, { w: -o.w }]; }).take(10).toArray(); \
             var z = Iterator.zip([big.values(), big.slice(10).values()], \
               { mode: 'longest', padding: [{ v: -1 }, { v: -2 }] }).toArray(); \
             var k = Iterator.zipKeyed({ a: big.values(), b: ['x', 'y'], 7: big.values() }).toArray(); \
             var c = Iterator.concat(big.slice(0, 3), new Set([{ v: 99 }])).toArray(); \
             var s = big.values().reduce(function (acc, o) { return { v: acc.v + o.v }; }, { v: 0 }); \
             [r.map(function (o) { return o.w; }).join('/'), z.length, z[49][1].v, k.length, k[1].b, k[1][7].v, c.length, c[3].v, s.v].join()",
        ) {
            Ok(Outcome::Value(v)) => scope.to_text(v).unwrap_or_default(),
            _ => "failed".into(),
        }
    });
    assert_eq!(got, "0/0/6/-6/12/-12/18/-18/24/-24,50,-2,2,y,1,4,99,1225");
}

